import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G)); print(G['Demo pair 1 input'])

def transform(g):
    H,W=len(g),len(g[0])
    sep=min(c for c in range(W) if all(g[r][c]==0 for r in range(H)))
    left=[row[:sep] for row in g]
    right=[row[sep+1:] for row in g]
    lc=left[0][0]
    from collections import deque
    def comps(grid, target):
        seen=set(); out=[]
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c]==target and (r,c) not in seen:
                    q=deque([(r,c)]); seen.add((r,c)); cells=[]
                    while q:
                        y,x=q.popleft(); cells.append((y,x))
                        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(grid) and 0<=nx<len(grid[0]) and grid[ny][nx]==target and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                    out.append(cells)
        return out
    def norm(cells):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        y0,x0=min(ys),min(xs)
        return frozenset((y-y0,x-x0) for y,x in cells)
    holes=comps(left,0)
    shapes={}
    for col in set(v for row in right for v in row):
        if col!=0:
            for cells in comps(right,col):
                shapes[norm(cells)]=col
    out=[row[:] for row in left]
    for cells in holes:
        col=shapes[norm(cells)]
        for y,x in cells: out[y][x]=col
    return out

